  "craft.weaving.funFact": "بنارسی بروکیڈ کے بنکاروں کو باریک زری کے کام والی ایک ریشمی ساڑھی مکمل کرنے میں ایک مہینے تک کا وقت لگ سکتا ہے۔",
  "craft.block-printing.funFact": "ایک اجرک بلاک پرنٹ ڈیزائن کو اپنے مکمل گہرے رنگ تک پہنچنے کے لیے رنگائی، دھلائی اور خشک کرنے کے 16 مراحل تک کی ضرورت پڑ سکتی ہے۔",
  "craft.pottery.funFact": "نظام آباد کے کالے مٹی کے برتنوں کو ان کی چمکدار کالی چمک دھوئیں سے بھری، آکسیجن سے خالی بھٹی میں پکانے سے ملتی ہے، کسی رنگ یا گلیز سے نہیں۔",
  "craft.metalwork.funFact": "بدری کاری گری میں چاندی کی نقش نگاری ایک ایسے مرکب دھات میں کی جاتی ہے جسے بیدر کے قلعے کے قریب ملنے والی خاص مٹی سے سیاہ کیا جاتا ہے۔",
  "craft.woodwork.funFact": "چنّاپٹنہ کے لکڑی کے کھلونے آج بھی 200 سال پرانی خراد تکنیک پر نباتاتی رنگوں سے پالش کیے جاتے ہیں۔",
  "craft.embroidery.funFact": "لکھنؤ کے ایک چکن کاری لباس میں سوئی سے کی گئی درجنوں مختلف کڑھائی کی سلائیاں ہو سکتی ہیں۔",
  "craft.painting.funFact": "روایتی مدھوبنی مصوری بہار میں خواتین کے اپنے گھروں کی مٹی کی دیواروں پر بنائی گئی تصویروں سے شروع ہوئی تھی۔",
  "craft.basketry.funFact": "مونج گھاس کی ٹوکری بُنائی ایک جنگلی سیلابی علاقے کی گھاس کو پائیدار، مکمل طور پر حیاتیاتی طور پر گلنے والی گھریلو اشیاء میں بدل دیتی ہے۔",
  "craft.jewellery.funFact": "کٹک کی چاندی کی تارکشی بال سے بھی باریک چاندی کے تار سے تیار کی جاتی ہے۔",
  "craft.leather.funFact": "کولہاپوری چپلیں روایتی طور پر مکمل طور پر ہاتھ سے سلی جاتی ہیں، بغیر کسی کیل یا مشین کی سلائی کے۔",
  "craft.stone.funFact": "آگرہ کے پتھر کی نقش نگاری کرنے والے کاریگر آج بھی وہی پیترا دورا تکنیک استعمال کرتے ہیں جو تاج محل کو سجاتی ہے۔",
  "craft.bamboo.funFact": "ایک بانس کا پودا صرف 3-5 سالوں میں دستکاری کے قابل استعمال ہو سکتا ہے، جو سخت لکڑی کے درختوں سے کہیں زیادہ تیز ہے۔",
  "tips.modal.title": "آج کی تجویز",
  "tips.modal.gotIt": "سمجھ گیا",
  "tips.priceFloor": "ہمیشہ اپنی لاگت کی حد سے اوپر قیمت رکھیں — خام مال، آپ کا وقت اور پلیٹ فارم فیس — سست مہینے میں بھی۔",
  "tips.trackIncome": "ہر فروخت درج کریں، چاہے وہ چھوٹی ہی کیوں نہ ہو۔ ایک آسان آمدنی کا ریکارڈ آپ کو کمزور موسم کی منصوبہ بندی کرنے اور قرض کے لیے آمدنی ثابت کرنے میں مدد کرتا ہے۔",
  "tips.bulkOrders": "بڑے اور ادارہ جاتی آرڈر مستقل اور پیشگی ادائیگی کرتے ہیں۔ اپنی گنجائش اور تیاری کا وقت اپ ڈیٹ رکھیں تاکہ خریدار آپ کو تلاش کر سکیں۔",
  "tips.photoQuality": "واضح، اچھی روشنی میں اور کئی زاویوں سے لی گئی تصاویر والی فہرستیں جلدی فروخت ہوتی ہیں۔ قدرتی روشنی فلیش سے بہتر کام کرتی ہے۔",
  "tips.respondFast": "جب آپ ایک دن کے اندر سوالات کا جواب دیتے ہیں تو خریداروں کے آرڈر مکمل کرنے کا امکان زیادہ ہوتا ہے۔",
  "tips.saveSavings": "ہر ادائیگی کا ایک چھوٹا حصہ بچت کے طور پر الگ رکھیں — 5% بھی جمع ہو کر آرڈرز کے درمیان آپ کی مدد کرتا ہے۔",
  "tips.giPremium": "GI ٹیگ اصل مقام کا ثبوت ہے جس پر خریدار بھروسہ کرتے ہیں۔ تصدیق شدہ اشیاء کی قیمت اکثر زیادہ رکھی جا سکتی ہے — اپنی چیز کی قیمت کم نہ آنکیں۔",
  "tips.restockEarly": "خام مال ختم ہونے سے پہلے ہی دوبارہ منگوانا شروع کریں، خاص طور پر تہوار اور شادی کے موسم سے پہلے جب مانگ بڑھ جاتی ہے۔",
  "tips.clusterSupport": "آپ کا کلسٹر کوآرڈینیٹر بڑی مقدار میں مواد خریدنے اور تربیت میں مدد کر سکتا ہے — کسی مسئلے کے سنگین ہونے سے پہلے ہی رابطہ کریں۔",
  "tips.storySells": "کہانی والی اشیاء کے لیے خریدار زیادہ قیمت ادا کرتے ہیں۔ اپنی تکنیک یا دستکاری کی تاریخ کے بارے میں ایک مختصر نوٹ اپنی فہرست میں شامل کریں۔",
